steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key workflowStates { nodes { id name archivedAt } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key } } workflowStates { nodes { id name teamId } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key } } workflowStates { nodes { id name team { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { workflowStateArchive(id: \"t-web-st-blocked\") { success errors { message path } state { id name archivedAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"WorkflowStateArchivePayload\") { name fields { name type { name kind ofType { name } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { workflowStateArchive(id: \"t-web-st-blocked\") { success entity { id name archivedAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { workflowState: { name: { eq: \"Blocked\" } }, team: { key: { eq: \"WEB\" } } }) { nodes { id identifier name state { id name } archivedAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"IssueFilter\") { name fields { name type { name kind ofType { name } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { a: __type(name: \"IssueFilter\") { name kind inputFields { name type { name kind ofType { name } } } interfaces { name } } b: __type(name: \"Issue\") { name fields { name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { state: { name: { eq: \"Blocked\" } }, team: { key: { eq: \"WEB\" } } }) { nodes { id identifier title state { id name } archivedAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { a: issueUpdate(id: \"i-web-2\", input: { stateId: \"t-web-st-2\" }) { success issue { id identifier state { id name } } } b: issueUpdate(id: \"i-web-3\", input: { stateId: \"t-web-st-2\" }) { success issue { id identifier state { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "mutation { workflowStateArchive(id: \"t-web-st-blocked\") { success entity { id name archivedAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "query { workflowStates(filter: { team: { id: { eq: \"t-web\" } } }) { nodes { id name archivedAt } } }"
  }'
